class Solution {
public:
    int maxScore(vector<int>& nums, int maxVal) {
        int n = nums.size();
        int M = max(maxVal,
                    *max_element(nums.begin(), nums.end()));

        vector<int> freq(M + 1, 0);

        for (int x : nums)
            freq[x]++;

        // Step 1: Compute Mobius function.
        vector<int> mu(M + 1, 0);
        vector<int> lp(M + 1, 0);
        vector<int> primes;

        mu[1] = 1;

        for (int i = 2; i <= M; ++i) {
            if (lp[i] == 0) {
                lp[i] = i;
                primes.push_back(i);
                mu[i] = -1;
            }

            for (int p : primes) {
                long long v = 1LL * i * p;

                if (v > M)
                    break;

                lp[v] = p;

                if (i % p == 0) {
                    mu[v] = 0;
                    break;
                }

                mu[v] = -mu[i];
            }
        }

        // Step 2: Count multiples of each divisor.
        vector<int> divisible(M + 1, 0);

        for (int d = 1; d <= M; ++d) {
            for (int j = d; j <= M; j += d) {
                divisible[d] += freq[j];
            }
        }

        // Step 3: Count elements coprime to each x.
        vector<int> coprime(M + 1, 0);

        for (int d = 1; d <= M; ++d) {
            if (mu[d] == 0)
                continue;

            int contribution = mu[d] * divisible[d];

            for (int x = d; x <= M; x += d) {
                coprime[x] += contribution;
            }
        }

        // Step 4: Calculate maximum score.
        int ans = 0;

        for (int x = 1; x <= M; ++x) {
            int bad = n - coprime[x];

            if (freq[x] > 0) {
                // Select an existing occurrence of x.
                // That occurrence does not need modification.
                ans = max(ans, x - bad + (x > 1));
            }
            else if (x <= maxVal) {
                // Create x by changing one element.
                int cost = max(1, bad);
                ans = max(ans, x - cost);
            }
        }

        return ans;
    }
};
